CREATE TABLE IF NOT EXISTS users (name TEXT PRIMARY KEY COLLATE NOCASE, display TEXT NOT NULL, salt TEXT NOT NULL, hash TEXT NOT NULL, found TEXT NOT NULL DEFAULT '[]', ver INTEGER NOT NULL DEFAULT 0, share INTEGER NOT NULL DEFAULT 1, public INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (ip TEXT NOT NULL, t INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_ip ON attempts(ip, t);
CREATE TABLE IF NOT EXISTS submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, entry TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', who TEXT NOT NULL DEFAULT '', account TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'new', note TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS submissions_status ON submissions(status, created);
CREATE TABLE IF NOT EXISTS overrides (id TEXT PRIMARY KEY, data TEXT NOT NULL, updated INTEGER NOT NULL, by TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS friends (name TEXT NOT NULL COLLATE NOCASE, friend TEXT NOT NULL COLLATE NOCASE, created INTEGER NOT NULL, PRIMARY KEY (name, friend));
CREATE TABLE IF NOT EXISTS counts (name TEXT PRIMARY KEY COLLATE NOCASE, data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS activity (name TEXT NOT NULL COLLATE NOCASE, id TEXT NOT NULL DEFAULT '', n INTEGER NOT NULL DEFAULT 1, t INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS activity_name_t ON activity(name, t);
CREATE TABLE IF NOT EXISTS changes (id INTEGER PRIMARY KEY AUTOINCREMENT, entry TEXT NOT NULL, before TEXT, after TEXT, by TEXT NOT NULL DEFAULT '', what TEXT NOT NULL DEFAULT '', t INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS blocks (id INTEGER PRIMARY KEY AUTOINCREMENT, ip TEXT NOT NULL DEFAULT '', account TEXT NOT NULL DEFAULT '' COLLATE NOCASE, note TEXT NOT NULL DEFAULT '', by TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS blocks_ip ON blocks(ip);
CREATE TABLE IF NOT EXISTS subip (sub INTEGER PRIMARY KEY, ip TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS anon (device TEXT PRIMARY KEY, found TEXT NOT NULL DEFAULT '[]', updated INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS anon_updated ON anon(updated);
ALTER TABLE submissions ADD COLUMN token TEXT NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS submissions_token ON submissions(token);
CREATE TABLE IF NOT EXISTS transfers (code TEXT PRIMARY KEY, data TEXT NOT NULL, created INTEGER NOT NULL);
